#!/usr/bin/env node

const fs = require("node:fs");
const path = require("node:path");

const ROOT = path.resolve(__dirname, "..");
const OUTPUT_PATH = path.join(ROOT, "data/canonical/contexts.js");
const SOURCES = Object.freeze([
  ["leagueSports", "data/canonical/afl-nrl-2026.json"],
  ["f1Context", "data/canonical/f1-context-2026.json"],
  ["tennisContext", "data/canonical/tennis-context-2026.json"],
  ["cyclingContext", "data/canonical/cycling-context-2026.json"],
  ["nbaContext", "data/canonical/nba-context-2026.json"],
  ["cwgContext", "data/canonical/cwg-context-2026.json"],
]);

function readContexts(){
  return Object.fromEntries(SOURCES.map(([key, relativePath]) => [
    key,
    JSON.parse(fs.readFileSync(path.join(ROOT, relativePath), "utf8")),
  ]));
}

function renderBundle(contexts = readContexts()){
  return `/* Generated by scripts/build-canonical-context-bundle.js. Canonical JSON remains authoritative. */\nglobalThis.NOTHINGSPORTS_CANONICAL_CONTEXTS = ${JSON.stringify(contexts)};\n`;
}

function main(argv = process.argv.slice(2)){
  const output = renderBundle();
  if (argv.includes("--check")){
    const current = fs.existsSync(OUTPUT_PATH) ? fs.readFileSync(OUTPUT_PATH, "utf8") : "";
    if (current !== output){
      console.error("Generated canonical context bundle is stale. Run node scripts/build-canonical-context-bundle.js.");
      process.exit(1);
    }
    console.log("Canonical direct-file context bundle matches all authoritative JSON sources.");
    return;
  }
  fs.writeFileSync(OUTPUT_PATH, output);
  console.log(`Canonical direct-file context bundle written: ${path.relative(ROOT, OUTPUT_PATH)}.`);
}

if (require.main === module) main();

module.exports = {
  OUTPUT_PATH,
  SOURCES,
  readContexts,
  renderBundle,
};
